package com.mohymods.kingdomsmp.profession;
import java.util.*;
import net.minecraft.nbt.*;
/** Bounded world-local observations of successful native hive production; never grants items or currency. */
public final class ApiaryEvidence {
 public static final Set<String> SPECIES=Set.of("productivebees:iron","productivebees:copper");
 public record Site(String dimension,long pos){public Site{if(!dimension.equals("minecraft:overworld"))throw new IllegalArgumentException("Unvalidated apiary dimension");}}
 public record Observation(String species,UUID bee,long time,int produced){public Observation{if(!SPECIES.contains(species)||bee==null||time<0||produced<1||produced>4096)throw new IllegalArgumentException("Invalid native bee observation");}}
 private final Map<Site,Map<String,Observation>> sites=new HashMap<>();
 public void record(Site site,Observation observation){if(!sites.containsKey(site)&&sites.size()>=8192)return;sites.computeIfAbsent(site,k->new HashMap<>()).put(observation.species(),observation);}
 public void remove(Site site){sites.remove(site);}public Map<String,Observation> at(Site site){return Map.copyOf(sites.getOrDefault(site,Map.of()));}
 public CompoundTag save(){var root=new CompoundTag();root.putInt("schema",1);var list=new ListTag();sites.entrySet().stream().sorted(Comparator.comparing((Map.Entry<Site,Map<String,Observation>> e)->e.getKey().dimension()).thenComparingLong(e->e.getKey().pos())).forEach(e->{var row=new CompoundTag();row.putString("dimension",e.getKey().dimension());row.putLong("pos",e.getKey().pos());var observations=new ListTag();e.getValue().values().stream().sorted(Comparator.comparing(Observation::species)).forEach(o->{var item=new CompoundTag();item.putString("species",o.species());item.putUUID("bee",o.bee());item.putLong("time",o.time());item.putInt("produced",o.produced());observations.add(item);});row.put("observations",observations);list.add(row);});root.put("sites",list);return root;}
 public static ApiaryEvidence load(CompoundTag tag){if(!tag.getAllKeys().equals(Set.of("schema","sites"))||!tag.contains("schema",Tag.TAG_INT)||tag.getInt("schema")!=1)throw new IllegalArgumentException("Invalid apiary schema");var result=new ApiaryEvidence();for(var value:rows(tag,"sites",8192)){var row=(CompoundTag)value;if(!row.getAllKeys().equals(Set.of("dimension","pos","observations"))||!row.contains("dimension",Tag.TAG_STRING)||!row.contains("pos",Tag.TAG_LONG))throw new IllegalArgumentException("Invalid apiary site");var site=new Site(row.getString("dimension"),row.getLong("pos"));if(result.sites.containsKey(site))throw new IllegalArgumentException("Duplicate apiary site");var map=new HashMap<String,Observation>();for(var entry:rows(row,"observations",2)){var o=(CompoundTag)entry;if(!o.getAllKeys().equals(Set.of("species","bee","time","produced"))||!o.contains("species",Tag.TAG_STRING)||!o.hasUUID("bee")||!o.contains("time",Tag.TAG_LONG)||!o.contains("produced",Tag.TAG_INT))throw new IllegalArgumentException("Invalid native observation");var obs=new Observation(o.getString("species"),o.getUUID("bee"),o.getLong("time"),o.getInt("produced"));if(map.put(obs.species(),obs)!=null)throw new IllegalArgumentException("Duplicate bee species");}if(map.isEmpty())throw new IllegalArgumentException("Empty apiary site");result.sites.put(site,map);}return result;}
 private static ListTag rows(CompoundTag root,String key,int max){if(!(root.get(key) instanceof ListTag list)||list.size()>max||!list.isEmpty()&&list.getElementType()!=Tag.TAG_COMPOUND)throw new IllegalArgumentException("Invalid apiary rows");return list;}
}
